 android.os.Bundle state(){android.os.Bundle b=image.state();b.putString("uri",photo.uri);b.putString("name",photo.name);b.putBoolean("repositoryBacked",repositoryBacked);b.putBoolean("expanded",expanded);b.putBoolean("chrome",chrome);return b;}
